<?php
require_once __DIR__ . '/../includes/auth.php';
wajibRole('pengelola');
require_once __DIR__ . '/../config/database.php';
$cari = trim($_GET['cari'] ?? '');
$mulai = trim($_GET['mulai'] ?? '');
$sampai = trim($_GET['sampai'] ?? '');
$sql = "SELECT l.*, u.nama, u.username FROM activity_logs l LEFT JOIN users u ON u.id_user=l.id_user WHERE 1=1";
$params=[];
if ($cari !== '') { $sql .= " AND (l.aktivitas LIKE :a OR l.modul LIKE :m OR l.data_diproses LIKE :d OR u.nama LIKE :n OR u.username LIKE :u)"; foreach(['a','m','d','n','u'] as $k) $params[$k]='%'.$cari.'%'; }
if ($mulai !== '') { $sql .= ' AND l.waktu_aktivitas >= :mulai'; $params['mulai']=$mulai.' 00:00:00'; }
if ($sampai !== '') { $sql .= ' AND l.waktu_aktivitas <= :sampai'; $params['sampai']=$sampai.' 23:59:59'; }
$sql .= ' ORDER BY l.waktu_aktivitas DESC LIMIT 500';
try { $st=$pdo->prepare($sql); $st->execute($params); $data=$st->fetchAll(); } catch(PDOException $e) { $data=[]; $error='Tabel atau kolom log belum sesuai. Pastikan tabel activity_logs memiliki kolom waktu_aktivitas.'; }
function eLog($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Riwayat Aktivitas | KosSpace</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css" rel="stylesheet"><link href="../assets/css/app.css" rel="stylesheet"></head><body><div class="app-shell d-flex"><?php include __DIR__.'/../includes/admin_sidebar.php'; ?><main class="app-main"><header class="topbar"><div><div class="topbar-kicker">Administrasi</div><div class="topbar-title">Riwayat aktivitas</div></div><div class="user-chip"><div class="user-name"><?=eLog($_SESSION['nama']??'Pengelola')?></div><a href="../logout.php" class="btn btn-outline-secondary ms-2"><i class="bi bi-box-arrow-right"></i></a></div></header><section class="page-heading"><div><div class="eyebrow">Audit trail</div><h1>Riwayat Aktivitas</h1><p>Catatan aktivitas pengguna untuk membantu penelusuran perubahan data.</p></div></section><?php if(!empty($error)):?><div class="alert alert-warning"><?=eLog($error)?></div><?php endif;?><section class="panel"><form method="get" class="row g-2 mb-4"><div class="col-md-5"><input class="form-control" name="cari" value="<?=eLog($cari)?>" placeholder="Cari pengguna, aktivitas, modul..."></div><div class="col-md-3"><input type="date" class="form-control" name="mulai" value="<?=eLog($mulai)?>"></div><div class="col-md-3"><input type="date" class="form-control" name="sampai" value="<?=eLog($sampai)?>"></div><div class="col-md-1"><button class="btn btn-primary w-100"><i class="bi bi-search"></i></button></div></form><div class="table-responsive"><table class="table table-hover align-middle"><thead><tr><th>Waktu</th><th>Pengguna</th><th>Aktivitas</th><th>Modul</th><th>Data diproses</th></tr></thead><tbody><?php if(!$data):?><tr><td colspan="5" class="text-center text-secondary py-4">Belum ada data aktivitas atau tidak ada hasil yang cocok.</td></tr><?php else: foreach($data as $r):?><tr><td class="text-nowrap"><?=eLog($r['waktu_aktivitas']??$r['created_at']??'-')?></td><td><?=eLog($r['nama']??'Pengguna dihapus')?> <small class="text-secondary d-block"><?=eLog($r['username']??'')?></small></td><td><?=eLog($r['aktivitas']??'-')?></td><td><?=eLog($r['modul']??'-')?></td><td><?=eLog($r['data_diproses']??'-')?></td></tr><?php endforeach; endif;?></tbody></table></div><div class="form-hint">Ditampilkan maksimal 500 aktivitas terbaru.</div></section><footer class="app-footer">&copy; <?=date('Y')?> KosSpace · Sistem Informasi Pengelolaan Kos Mahasiswa</footer></main></div></body></html>